#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;
    long long p;
    long long m;
    long long k;
    long long target;
    cin >> p >> m >> k >> target;

    int n = s.size();
    long long pk = 1;
    for (int i = 0; i < k; i++) pk = pk * p % m;
    long long h = 0;
    int answer = -1;
    for (int i = n - 1; i >= 0; i--) {
        h = (h * p + (s[i] - 'a' + 1)) % m;
        if (i + k < n) h = ((h - (s[i + k] - 'a' + 1) * pk) % m + m) % m;
        if (i + k <= n && h == target) answer = i;
    }
    cout << answer << "\n";

    return 0;
}

